l: Timing methods for recording."], ["Bank feed","Profession term \u2014 Bank feed: Automatic transaction import."], ["Categorization","Profession term \u2014 Categorization: Assigning transactions to accounts."], ["Write-off","Profession term \u2014 Write-off: Removing uncollectible amounts."], ["1099 filing","Profession term \u2014 1099 filing: Contractor reporting."], ["Sales tax","Profession term \u2014 Sales tax: Collection and remittance duties."], ["Petty cash","Profession term \u2014 Petty cash: Small cash fund controls."], ["Fixed assets","Profession term \u2014 Fixed assets: Long-term property tracking."], ["Depreciation","Profession term \u2014 Depreciation: Spreading asset costs."], ["Cleanup","Profession term \u2014 Cleanup: Fixing messy historical books."], ["Monthly package","Profession term \u2014 Monthly package: The recurring client deliverable."]];
function ask(n){var out=[],seen={};n=Math.min(n,ITEMS.length);for(var k=0;k<n;k++){var it=ITEMS[(Math.random()*ITEMS.length)|0];out.push("Q"+(k+1)+": "+it[0]+"\nA"+(k+1)+": "+it[1]);}return out.join("\n\n");}
function lookup(q){q=String(q).toLowerCase();var h=[];for(var i=0;i<ITEMS.length;i++){if((ITEMS[i][0]+" "+ITEMS[i][1]).toLowerCase().indexOf(q)>=0)h.push(ITEMS[i][0]+" — "+ITEMS[i][1]);}return h.length?h.join("\n"):"no match for "+q;}
